import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
  random,
  Easing,
  Sequence,
} from '../remotionShim';
import { noise2D } from "@remotion/noise";

{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type AttentionAlgorithmProps = Record<string, any>;

// Helper for random data stream generation
const DataStream: React.FC<{
  color: string;
  x: number;
  y: number;
  seed: string;
}> = ({ color, x, y, seed }) => {
  const frame = useCurrentFrame();
  const val = Math.floor(random(`${seed}-${Math.floor(frame / 4)}`) * 99999); // Update every 4 frames
  const opacity = random(`${seed}-op-${frame}`) > 0.5 ? 1 : 0.3;

  return (
    <div
      style={{
        position: "absolute",
        left: x,
        top: y,
        color: color,
        fontFamily: "Share Tech Mono",
        fontSize: 12,
        opacity,
      }}
    >
      {val.toString(16).toUpperCase()}
    </div>
  );
};

const AttentionAlgorithm: React.FC<AttentionAlgorithmProps> = ({
  backgroundColor = "#050505",
  transparentBackground = false,
  durationInSeconds = 5,
  primaryColor = "#00ff41",
  accentColor = "#ff003c",
  contentTitle = "ATTENTION_SPAN",
  verdictText = "MOMENTUM_LOST",
  scanSpeed = 1.5,
}) => {
  useFontLoader(["Share Tech Mono", "JetBrains Mono"]);
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  
  // Timing Constants
  const entryFrame = 0;
  const scanStartFrame = 20;
  const scanDuration = fps * scanSpeed;
  const decisionFrame = scanStartFrame + scanDuration; // When the verdict hits
  const collapseFrame = decisionFrame + 20; // When it disappears

  // --- Animation Phases ---

  // 1. ENTRY: Spring load up
  const entrySpring = spring({
    frame: frame - entryFrame,
    fps,
    config: { damping: 14, stiffness: 100 },
  });
  
  // 2. SCANNING: Vertical line movement
  const scanProgress = interpolate(
    frame,
    [scanStartFrame, decisionFrame],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // 3. JITTER: Noise applied during scan phase only
  const noiseValX = noise2D("shake-x", frame / 5, 0);
  const noiseValY = noise2D("shake-y", 0, frame / 5);
  
  const isScanning = frame >= scanStartFrame && frame < decisionFrame;
  const shakeIntensity = isScanning ? 10 : 0;
  const offsetX = noiseValX * shakeIntensity;
  const offsetY = noiseValY * shakeIntensity;

  // 4. COLLAPSE: "TV Off" effect
  // First scale X to almost 0, then Scale Y to 0
  const collapseProgress = spring({
    frame: frame - collapseFrame,
    fps,
    config: { stiffness: 200, damping: 20 },
  });

  const scaleX = interpolate(
    frame, 
    [collapseFrame, collapseFrame + 5], 
    [1, 0.02], 
    { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.exp }
  );
  
  const scaleY = interpolate(
    frame, 
    [collapseFrame + 5, collapseFrame + 10], 
    [1, 0], 
    { extrapolateLeft: "clamp", extrapolateRight: "clamp", easing: Easing.exp }
  );

  // 5. COLOR SHIFT: Turns to accent color on decision
  const cardBorderColor = frame > decisionFrame ? accentColor : primaryColor;
  const cardOpacity = interpolate(frame, [collapseFrame + 8, collapseFrame + 12], [1, 0], { extrapolateLeft: 'clamp', extrapolateRight: 'clamp'});

  // Background Grid Movement
  const gridOffset = (frame * 10) % 50;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Share Tech Mono", overflow: "hidden" }}>
      
      {/* Dynamic Background Grid */}
      <AbsoluteFill style={{ opacity: 0.2 }}>
        {Array.from({ length: 20 }).map((_, i) => (
          <div
            key={i}
            style={{
              position: "absolute",
              left: 0,
              right: 0,
              top: (i * 100) + gridOffset - 100,
              height: 1,
              backgroundColor: primaryColor,
            }}
          />
        ))}
         {Array.from({ length: 12 }).map((_, i) => (
          <div
            key={`v-${i}`}
            style={{
              position: "absolute",
              top: 0,
              bottom: 0,
              left: (width / 10) * i,
              width: 1,
              backgroundColor: primaryColor,
            }}
          />
        ))}
      </AbsoluteFill>

      {/* Main Content Container */}
      <AbsoluteFill 
        style={{ 
          justifyContent: "center", 
          alignItems: "center",
          transform: `translate(${offsetX}px, ${offsetY}px)`
        }}
      >
        <div
          style={{
            width: width * 0.4,
            height: height * 0.5,
            border: `2px solid ${cardBorderColor}`,
            backgroundColor: "rgba(0,0,0,0.8)",
            position: "relative",
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            justifyContent: "center",
            boxShadow: `0 0 20px ${cardBorderColor}40`,
            transform: `translateY(${(1 - entrySpring) * 200}px) scaleX(${scaleX}) scaleY(${scaleY})`,
            opacity: cardOpacity,
          }}
        >
          {/* Header Status */}
          <div style={{
            position: "absolute", top: 10, left: 10, right: 10,
            display: "flex", justifyContent: "space-between",
            fontSize: 14, color: cardBorderColor
          }}>
            <span>ID: {random("id") > 0.5 ? "99X-A" : "44B-2"}</span>
            <span>{frame > decisionFrame ? "FINALIZED" : "EVALUATING..."}</span>
          </div>

          {/* Central Content */}
          <h1 style={{ 
            color: "#fff", 
            fontSize: 40, 
            textAlign: "center", 
            letterSpacing: 4,
            margin: 0,
            fontFamily: "JetBrains Mono",
            fontWeight: 800
          }}>
            {contentTitle}
          </h1>
          
          {/* Verdict Overlay */}
          {frame > decisionFrame && (
            <div style={{
              position: "absolute",
              color: accentColor,
              fontSize: 60,
              fontWeight: "bold",
              border: `4px solid ${accentColor}`,
              padding: "10px 20px",
              transform: `rotate(-10deg) scale(${spring({ frame: frame - decisionFrame, fps, config: { damping: 10 } })})`,
              backgroundColor: "rgba(0,0,0,0.9)",
              zIndex: 10
            }}>
              {verdictText}
            </div>
          )}

          {/* Scanning Line */}
          {isScanning && (
            <div
              style={{
                position: "absolute",
                left: 0,
                right: 0,
                height: 2,
                backgroundColor: primaryColor,
                boxShadow: `0 0 15px ${primaryColor}, 0 0 30px ${primaryColor}`,
                top: `${scanProgress * 100}%`,
                zIndex: 5
              }}
            />
          )}
          
          {/* Scan Grid Overlay on Card */}
          <div style={{
              position: "absolute", inset: 0, 
              backgroundImage: `linear-gradient(transparent 50%, ${cardBorderColor}20 50%)`,
              backgroundSize: "100% 4px",
              pointerEvents: "none"
          }} />
        </div>
      </AbsoluteFill>

      {/* HUD / Data Overlay */}
      <AbsoluteFill>
         <DataStream seed="d1" x={100} y={height * 0.2} color={primaryColor} />
         <DataStream seed="d2" x={width - 150} y={height * 0.3} color={primaryColor} />
         <DataStream seed="d3" x={100} y={height * 0.7} color={primaryColor} />
         <DataStream seed="d4" x={width - 150} y={height * 0.8} color={primaryColor} />

         {/* Momentum Bar */}
         <div style={{
           position: "absolute",
           bottom: 100,
           left: width / 2 - 150,
           width: 300,
           height: 4,
           backgroundColor: "#333",
           overflow: "hidden"
         }}>
           <div style={{
             width: "100%",
             height: "100%",
             backgroundColor: cardBorderColor,
             transform: `scaleX(${isScanning ? 1 - scanProgress : (frame > decisionFrame ? 0 : 1)})`,
             transformOrigin: "left center"
           }} />
         </div>
         <div style={{
            position: "absolute",
            bottom: 80,
            width: "100%",
            textAlign: "center",
            color: cardBorderColor,
            fontSize: 12,
            opacity: 0.8
         }}>
            SYSTEM_MOMENTUM // {isScanning ? Math.floor((1 - scanProgress) * 100) : (frame > decisionFrame ? 0 : 100)}%
         </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default AttentionAlgorithm;